import{_ as t,o as i,c as r,ag as o}from"./chunks/framework.7He2WLS4.js";const f=JSON.parse('{"title":"Certificate Setup Overview","description":"","frontmatter":{},"headers":[],"relativePath":"certificate/index.md","filePath":"certificate/index.md","lastUpdated":1772297611000}'),a={name:"certificate/index.md"};function s(c,e,n,d,h,l){return i(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="certificate-setup-overview" tabindex="-1">Certificate Setup Overview <a class="header-anchor" href="#certificate-setup-overview" aria-label="Permalink to &quot;Certificate Setup Overview&quot;">​</a></h1><p>To inspect HTTPS traffic, NectoProxy must decrypt and re-encrypt it on the fly. This page explains why a certificate is needed, how the process works, and where to find platform-specific setup instructions.</p><h2 id="why-certificates-are-needed" tabindex="-1">Why Certificates Are Needed <a class="header-anchor" href="#why-certificates-are-needed" aria-label="Permalink to &quot;Why Certificates Are Needed&quot;">​</a></h2><p>HTTPS encrypts traffic between your browser and the server using TLS. Under normal circumstances, no intermediary can read or modify this traffic -- that is the entire point of HTTPS.</p><p>To inspect HTTPS traffic, NectoProxy acts as a <strong>man-in-the-middle (MITM) proxy</strong>. It must terminate the TLS connection from the client, inspect the plaintext request, optionally modify it, and then establish a separate TLS connection to the upstream server. For this to work without triggering browser security warnings, your system must trust NectoProxy&#39;s root CA certificate.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>When NectoProxy intercepts an HTTPS request, the following process occurs:</p><ol><li><p><strong>Your browser sends a CONNECT request</strong> to the proxy, indicating it wants to establish a tunnel to the target host (e.g., <code>api.example.com:443</code>).</p></li><li><p><strong>NectoProxy generates a domain-specific certificate</strong> for <code>api.example.com</code>, signed by its own root CA. This certificate is created on the fly and cached for subsequent requests to the same domain.</p></li><li><p><strong>NectoProxy completes the TLS handshake</strong> with your browser using this generated certificate. Because your system trusts the NectoProxy root CA, the browser accepts this certificate as valid.</p></li><li><p><strong>NectoProxy establishes a separate TLS connection</strong> to the real <code>api.example.com</code> server and forwards the request.</p></li><li><p><strong>The response flows back</strong> through NectoProxy, which can inspect and optionally modify it before forwarding it to your browser.</p></li></ol><div class="tip custom-block"><p class="custom-block-title">Key Point</p><p>NectoProxy only intercepts traffic that is explicitly routed through its proxy. It does not interfere with any traffic that does not pass through <code>127.0.0.1:8888</code> (or whichever address you configured).</p></div><h2 id="certificate-location" tabindex="-1">Certificate Location <a class="header-anchor" href="#certificate-location" aria-label="Permalink to &quot;Certificate Location&quot;">​</a></h2><p>NectoProxy stores its certificates in the following directory:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.nectoproxy/certs/</span></span></code></pre></div><p>This directory contains:</p><table tabindex="0"><thead><tr><th>File</th><th>Description</th></tr></thead><tbody><tr><td><code>ca.pem</code></td><td>The root CA certificate (public key). This is the file you install in your system/browser trust store.</td></tr><tr><td><code>ca-key.pem</code></td><td>The root CA private key. Keep this secure -- it is used to sign per-domain certificates.</td></tr><tr><td><code>domain-certs/</code></td><td>Cached per-domain certificates, generated on the fly.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Security Considerations</p><ul><li>The root CA private key (<code>ca-key.pem</code>) should be protected. Anyone with access to this key can generate certificates trusted by your system.</li><li>NectoProxy&#39;s root CA is unique to your installation -- it is generated the first time you run NectoProxy.</li><li>When you are finished using NectoProxy, you can remove the CA from your trust store for maximum security.</li><li>NectoProxy <strong>only</strong> intercepts traffic that passes through its proxy server. Applications not configured to use the proxy are unaffected.</li></ul></div><h2 id="clearing-the-certificate-cache" tabindex="-1">Clearing the Certificate Cache <a class="header-anchor" href="#clearing-the-certificate-cache" aria-label="Permalink to &quot;Clearing the Certificate Cache&quot;">​</a></h2><p>If you need to regenerate domain certificates (for example, after changing your CA or encountering certificate issues), you can clear the domain certificate cache:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cert</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --clear-cache</span></span></code></pre></div><p>This removes all cached per-domain certificates. They will be regenerated on the fly as new HTTPS requests come in.</p><h2 id="platform-setup-guides" tabindex="-1">Platform Setup Guides <a class="header-anchor" href="#platform-setup-guides" aria-label="Permalink to &quot;Platform Setup Guides&quot;">​</a></h2><p>Follow the guide for your operating system and browser:</p><table tabindex="0"><thead><tr><th>Platform</th><th>Guide</th></tr></thead><tbody><tr><td><strong>macOS</strong></td><td><a href="/nectoproxy/certificate/macos.html">macOS Certificate Setup</a></td></tr><tr><td><strong>Windows</strong></td><td><a href="/nectoproxy/certificate/windows.html">Windows Certificate Setup</a></td></tr><tr><td><strong>Linux</strong></td><td><a href="/nectoproxy/certificate/linux.html">Linux Certificate Setup</a></td></tr><tr><td><strong>Firefox</strong></td><td><a href="/nectoproxy/certificate/firefox.html">Firefox Certificate Setup</a> (all platforms)</td></tr><tr><td><strong>iOS / Android</strong></td><td><a href="/nectoproxy/certificate/mobile.html">Mobile Device Setup</a></td></tr></tbody></table><details class="details custom-block"><summary>Why Does Firefox Need a Separate Guide?</summary><p>Firefox uses its own certificate store (NSS) instead of the operating system&#39;s trust store. Even if you install the NectoProxy CA at the system level, Firefox will not trust it unless you either import it into Firefox&#39;s certificate manager or enable a Firefox setting to use system certificates. See the <a href="/nectoproxy/certificate/firefox.html">Firefox guide</a> for details.</p></details>',23)])])}const u=t(a,[["render",s]]);export{f as __pageData,u as default};
